package com.tester;
import org.junit.jupiter.api.Test;import com.tester.entity.*;import com.tester.repository.TestSuiteRepository;import com.tester.service.RelatorioJiraService;import org.apache.poi.xssf.usermodel.XSSFWorkbook;import org.apache.poi.ss.usermodel.BorderStyle;import java.io.ByteArrayInputStream;import java.time.LocalDate;import java.util.Optional;import static org.mockito.Mockito.*;import static org.assertj.core.api.Assertions.*;
class ExcelLayoutTest {@Test void preservesOriginalSuiteWorkbookStructure()throws Exception{var repository=mock(TestSuiteRepository.class);var plan=new TestPlan();plan.setName("Descrição de regressão");plan.setJira("QA-10");plan.setCallNumber("123");var tester=new TesterQA();tester.setName("Tester");plan.setTester(tester);var suite=new TestSuite();suite.setTestPlan(plan);suite.setData(LocalDate.of(2026,9,9));when(repository.findById(1L)).thenReturn(Optional.of(suite));byte[] data=new RelatorioJiraService(repository).gerarRelatorioJiraExcel(1L);try(var workbook=new XSSFWorkbook(new ByteArrayInputStream(data))){var sheet=workbook.getSheet("Relatório Jira");assertThat(sheet).isNotNull();assertThat(sheet.getRow(0).getCell(0).getStringCellValue()).isEqualTo("Data");assertThat(sheet.getRow(1).getCell(0).getStringCellValue()).isEqualTo("Responsável");assertThat(sheet.getRow(2).getCell(4).getStringCellValue()).isEqualTo("Senha");assertThat(sheet.getMergedRegion(0).formatAsString()).isEqualTo("B5:E5");String[] headers={"Cenário","Resultado Esperado","Resultado Obtido","Evidência","Resultado"};for(int i=0;i<5;i++){var cell=sheet.getRow(5).getCell(i);assertThat(cell.getStringCellValue()).isEqualTo(headers[i]);assertThat(cell.getCellStyle().getBorderBottom()).isEqualTo(BorderStyle.THIN);assertThat(workbook.getFontAt(cell.getCellStyle().getFontIndex()).getBold()).isTrue();assertThat(sheet.getColumnWidth(i)).isGreaterThan(0);}}}}
